window.WebNodeUI={"html": "<div id=\"vpanel\"><div class=\"vbar\"><div class=\"vicons vcontrols\"><button type=\"button\" class=\"vicon \" id=\"vclose\" title=\"Chiudi\" aria-label=\"Chiudi\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><circle cx=\"7\" cy=\"7\" r=\"5\" fill=\"currentColor\"/></svg></button><button type=\"button\" class=\"vicon \" id=\"vtri\" title=\"Espandi o richiudi la mappa\" aria-label=\"Espandi o richiudi la mappa\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M7 2 L13 12 L1 12 Z\" fill=\"currentColor\"/></svg></button><button type=\"button\" class=\"vicon \" id=\"vfull\" title=\"Dividi lo schermo: sito e mappa\" aria-label=\"Dividi lo schermo: sito e mappa\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><rect x=\"2\" y=\"2\" width=\"10\" height=\"10\" fill=\"currentColor\"/></svg></button><button type=\"button\" id=\"switchside\" class=\"vicon zoom\" title=\"Sposta Web Node a sinistra\" aria-label=\"Sposta Web Node a sinistra\" hidden><svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\"><path d=\"M12 7H2M6 3L2 7L6 11\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"/></svg></button></div><div class=\"vicons vzoom\"><button type=\"button\" class=\"vicon zoom\" id=\"zoomin\" title=\"Ingrandisci\" aria-label=\"Ingrandisci\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7H11M7 3V11\" stroke=\"currentColor\" stroke-width=\"3\"/></svg></button><button type=\"button\" class=\"vicon zoom\" id=\"zoomout\" title=\"Riduci\" aria-label=\"Riduci\"><svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" aria-hidden=\"true\"><path d=\"M3 7H11\" stroke=\"currentColor\" stroke-width=\"3\"/></svg></button></div><span class=\"vaddr\"></span></div><div id=\"viewport\"><svg id=\"vmap\" viewBox=\"0 0 760 560\" role=\"img\" aria-label=\"Mappa del sito\"></svg></div><div class=\"vfoot\"><div class=\"vsearch\"><input id=\"vq\" placeholder=\"Sai gi\u00e0 cosa cercare?\" aria-label=\"Cerca nella mappa\"></div><div id=\"vstatus\" class=\"vstatus\"><span></span></div></div></div><div id=\"closeprompt\" hidden><span>chiudere web Node?</span><button type=\"button\" id=\"closeyes\" aria-label=\"S\u00ec, chiudi Web Node\">S\u00ec</button><button type=\"button\" id=\"closeno\" aria-label=\"No, mantieni Web Node aperto\">No</button></div>", "css": "/* Stile del pannello */\n.vwrap{padding:0;}\n.vpanel{background:#1b1a19;overflow:hidden;font-family:\"Helvetica Neue\",Helvetica,Arial,sans-serif;line-height:1.2;transition:opacity .3s ease;}\n.vbar{display:flex;align-items:center;gap:10px;padding:11px 15px;}\n.vaddr{font-size:12px;font-weight:500;color:#ffffff;}\n.vicons{margin-left:auto;display:flex;align-items:center;gap:6px;}\n.vicon{color:#76766f;cursor:pointer;display:inline-flex;transition:color .2s ease;}\n.vicon:hover,.vicon.on{color:#b62118;}\n.vfoot{padding:12px 15px;}\n.vsearch{display:flex;align-items:center;width:50%;height:36px;padding:0 12px;background:#2a2927;box-sizing:border-box;}\n.vsearch input{-webkit-appearance:none!important;appearance:none!important;border:0!important;border-radius:0!important;outline:0!important;box-shadow:none!important;background:transparent!important;margin:0!important;padding:0!important;height:100%!important;box-sizing:border-box!important;flex:1;font-size:12px;font-family:inherit;color:#ffffff;}\n.vsearch input:focus,.vsearch input:focus-visible{outline:0!important;box-shadow:none!important;border:0!important;background:transparent!important;}\n.vsearch input::placeholder{color:#76766f;}\n.vstatus{font-size:10px;margin-top:9px;min-height:14px;overflow:hidden;}\n.vstatus span{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;color:#616160;}\n.edge{stroke:#76766f;stroke-width:1.25;stroke-linecap:round;transition:stroke .3s,stroke-width .3s,opacity .5s;}\n.edge.hot{stroke:#ffffff;stroke-width:2;}\n.edge.redhot{stroke:#b62118;stroke-width:2.5;}\n.edge.hid{opacity:0;}\n.dot{cursor:pointer;transition:transform .2s ease-out,opacity .55s ease,stroke .3s;transform-box:fill-box;transform-origin:center;}\n.dot.filled{fill:#ffffff;stroke:#ffffff;stroke-width:1.5;}\n.dot.outline{fill:#1b1a19;stroke:#ffffff;stroke-width:1.5;}\n.dot.redpath{stroke:#b62118;stroke-width:2;}\n.dot.dim{stroke:#76766f;}\n.dot.hid{opacity:0;pointer-events:none;}\n.dot:hover{fill:#b62118;stroke:#b62118;transform:scale(1.4);}\n.dot.home:hover{fill:#ffffff;stroke:#ffffff;transform:scale(1.4);}\n.nlbl{font-size:11.5px;fill:#bdbcb8;font-family:\"Helvetica Neue\",Helvetica,Arial,sans-serif;pointer-events:none;transition:fill .3s ease;}\n.nlbl.bright{fill:#ffffff;}\n.nlbl.off{fill:#76766f;}\n\n[hidden]{display:none!important}\n\n*{box-sizing:border-box}html,body,#vpanel{margin:0;width:100%;height:100%;overflow:hidden;background:#1b1a19;min-width:0}\n#vpanel{display:flex;flex-direction:column;font-family:Helvetica,Arial,sans-serif}\n.vbar{flex:none;gap:8px;padding:12px}.vaddr{flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}\n.vicons{display:flex;flex:none;gap:5px;margin:0}\n.vicon{appearance:none;border:0!important;background:none!important;padding:4px;display:inline-flex;align-items:center;justify-content:center;color:#76766f;cursor:pointer;box-shadow:none;border-radius:0}\n.vicon:hover,.vicon.on,.vicon.zoom{color:#b62118}.vicon:focus-visible{outline:1px solid #b62118}\n#viewport{flex:1;min-height:0;overflow:hidden;position:relative}#vmap{display:block;width:100%;height:100%;background:#1b1a19}\n.vfoot{flex:none;padding:10px 12px}.vsearch{width:100%;height:34px}.vsearch input{min-width:0;width:100%}\n.vstatus{margin-top:5px;font-size:10px;height:14px;min-height:14px}.vstatus span{display:block;white-space:nowrap;text-overflow:ellipsis;overflow:hidden}\n\n:host{all:initial;display:block!important;position:fixed!important;z-index:2147483647!important;color-scheme:dark}\n#shell{position:relative;width:100%;height:100%;background:#1b1a19;box-sizing:border-box;border:1px solid #45443f;border-radius:10px;overflow:hidden;resize:both;min-width:280px;min-height:280px;box-shadow:0 12px 40px #0007}\n#shell.split{border-radius:16px;resize:none;box-shadow:0 8px 28px #0003;border:1px solid #45443f;min-width:0;min-height:0}\n#vpanel{border-radius:inherit}\n.vbar{cursor:move;user-select:none;touch-action:none}\n.split .vbar{cursor:default}\n.vicon{cursor:pointer}\n#closeprompt{position:absolute;left:10px;right:10px;bottom:80px;background:#1b1a19;border:1px solid #b62118;padding:10px;display:flex;gap:10px;align-items:center;justify-content:center;font:13px Helvetica,Arial,sans-serif;color:white;box-shadow:0 6px 20px #0008}\n#closeyes,#closeno{appearance:none;background:#b62118;color:white;border:0;width:32px;height:32px;padding:0;cursor:pointer;font:12px Helvetica,Arial,sans-serif;flex:none}\n#closeyes{border-radius:50%}#closeno{border-radius:0}\n[hidden]{display:none!important}\n\n#closeprompt{border:0;box-shadow:none;display:grid;grid-template-columns:28px 28px;justify-content:center;justify-items:center;gap:10px 12px;padding:10px;background:#1b1a19}\n#closeprompt>span{grid-column:1 / -1;white-space:nowrap;text-align:center}\n#closeyes,#closeno{width:28px;height:28px;border-radius:50%;background:#b62118;font-size:11px}\n\n.vbar{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr);align-items:center;gap:8px}\n.vcontrols{justify-self:start;gap:2px}.vzoom{justify-self:center}.vaddr{display:block;width:100%;text-align:right;justify-self:end}\n"};
